package view;

import database.DBConnection;import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.sql.*;

public class PaymentsFrame extends JFrame {
 private final int residentId;private final DefaultTableModel model=new DefaultTableModel(new String[]{"ID","Period","Amount (₹)","Due date","Status","Paid on"},0){public boolean isCellEditable(int r,int c){return false;}};
 public PaymentsFrame(int residentId){this.residentId=residentId;setTitle("Maintenance payments");setSize(800,500);setLocationRelativeTo(null);setDefaultCloseOperation(DISPOSE_ON_CLOSE);JPanel p=new JPanel(new BorderLayout(12,12));p.setBackground(new Color(250,245,235));p.setBorder(BorderFactory.createEmptyBorder(18,18,18,18));setContentPane(p);JLabel title=new JLabel("Maintenance Payments");title.setFont(new Font("Serif",Font.BOLD,25));p.add(title,BorderLayout.NORTH);JTable t=new JTable(model);t.setRowHeight(27);p.add(new JScrollPane(t),BorderLayout.CENTER);JPanel actions=new JPanel(new FlowLayout(FlowLayout.RIGHT));actions.setOpaque(false);JButton refresh=new JButton("Refresh"),record=LoginFrame.button("RECORD PAYMENT");actions.add(refresh);actions.add(record);p.add(actions,BorderLayout.SOUTH);refresh.addActionListener(e->load());record.addActionListener(e->markPaid(t));load();setVisible(true);}
 private void markPaid(JTable t){int row=t.getSelectedRow();if(row<0){JOptionPane.showMessageDialog(this,"Select a payment first.");return;}int id=(int)model.getValueAt(row,0);if(!"PENDING".equalsIgnoreCase(String.valueOf(model.getValueAt(row,4)))&&!"OVERDUE".equalsIgnoreCase(String.valueOf(model.getValueAt(row,4)))){JOptionPane.showMessageDialog(this,"This payment is already marked paid.");return;}String[] methods={"UPI","Cash","Bank transfer","Card"};String method=(String)JOptionPane.showInputDialog(this,"Select payment method (this records a payment; it does not process money):","Record payment",JOptionPane.QUESTION_MESSAGE,null,methods,methods[0]);if(method==null)return;int confirm=JOptionPane.showConfirmDialog(this,"Confirm that you have paid this maintenance amount?","Confirm payment",JOptionPane.YES_NO_OPTION);if(confirm!=JOptionPane.YES_OPTION)return;String sql="UPDATE \"A-partment\".payments SET status='PAID',payment_date=CURRENT_DATE,payment_method=? WHERE payment_id=? AND resident_id=? AND status IN ('PENDING','OVERDUE')";try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement(sql)){s.setString(1,method);s.setInt(2,id);s.setInt(3,residentId);int changed=s.executeUpdate();JOptionPane.showMessageDialog(this,changed==1?"Payment record marked as paid. No money was processed by this app.":"Payment record was not changed.");load();}catch(Exception ex){LoginFrame.showDbError(ex);}}
 private void load(){model.setRowCount(0);String sql="SELECT payment_id,month_year,amount,due_date,status,payment_date FROM \"A-partment\".payments WHERE resident_id=? ORDER BY due_date DESC";try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement(sql)){s.setInt(1,residentId);try(ResultSet r=s.executeQuery()){while(r.next())model.addRow(new Object[]{r.getInt(1),r.getString(2),r.getBigDecimal(3),r.getDate(4),r.getString(5),r.getDate(6)});}}catch(Exception ex){LoginFrame.showDbError(ex);}}
}
